using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering.Universal;using UnityEngine.UIElements;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.UIElements;using ProjectWait.M.Editor;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;
public static class VerifyInstallerRI
{
 const string D="Assets/M/CodexTemp/OutlineRendererTool_20261030~/";const string Fixture="Assets/M/CodexTemp/OutlineRendererToolValidation";static List<object> checks=new List<object>();
 static void Check(bool ok,string name){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);}
 static string Hash(string path){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path)));}
 public static async Task<string> Main()
 {
  if(Application.isPlaying)throw new Exception("Edit Mode required");checks.Clear();string error=null;OutlineRendererInstaller.Result first=null,second=null;OutlineRendererSetupWindow window=null;
  try{
   var current=EditorSceneManager.GetActiveScene();var owner=Object.FindFirstObjectByType<ElevatorSceneRendering>();Check(OutlineRendererInstaller.DetectPipeline(current)==owner.scenePipeline,"Auto detection prefers the scene pipeline over project quality settings");
   if(!AssetDatabase.IsValidFolder(Fixture))AssetDatabase.CreateFolder("Assets/M/CodexTemp","OutlineRendererToolValidation");
   var scenePath=Fixture+"/InstallerValidation.unity";if(!AssetDatabase.LoadMainAssetAtPath(scenePath))Check(AssetDatabase.CopyAsset("Assets/M/Scene/Elevator_Safety_Prototype.unity",scenePath),"Create isolated M scene for validation");
   var scene=EditorSceneManager.OpenScene(scenePath,OpenSceneMode.Single);var sourcePath="Assets/Settings/Project Configuration/Performance URP Config.asset";var source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(sourcePath);string before=Hash(sourcePath);Check(source,"Read-only source pipeline exists");
   var pso=new SerializedObject(source);var sourceRenderer=pso.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue;string rendererPath=AssetDatabase.GetAssetPath(sourceRenderer),rendererBefore=Hash(rendererPath);
   Check(EditorApplication.ExecuteMenuItem("Tools/Wait/강조 세팅"),"Tools > Wait > 강조 세팅 menu opens the tool");window=EditorWindow.GetWindow<OutlineRendererSetupWindow>();await Task.Delay(400);var root=window.rootVisualElement;Check(window.titleContent.text=="강조 세팅","Window title uses the requested name");Check(root.Q<Button>("install")!=null&&root.Q<ObjectField>("pipeline")!=null,"UI Toolkit layout and controls loaded");Check(root.Q<Button>("install").worldBound.width>100,"Install button has a real layout width");root.Q<ObjectField>("pipeline").value=source;
   var button=root.Q<Button>("install");button.Focus();using(var ev=NavigationSubmitEvent.GetPooled()){ev.target=button;button.SendEvent(ev);}await Task.Delay(500);first=window.LastResult;
   Check(first!=null,"Install executed through the UI Toolkit button submit event");Check(first.sceneLinked&&first.rendererPaths.Length>0,"Tool creates the feature and links the current scene");Check(first.pipeline!=source&&OutlineRendererInstaller.IsOwned(AssetDatabase.GetAssetPath(first.pipeline))&&first.rendererPaths.All(OutlineRendererInstaller.IsOwned)&&first.createdAssets.All(OutlineRendererInstaller.IsOwned),"External pipeline and renderers are copied only to M");Check(Hash(sourcePath)==before&&Hash(rendererPath)==rendererBefore,"Source pipeline and renderer bytes are unchanged");
   var newOwner=Object.FindFirstObjectByType<ElevatorSceneRendering>();Check(newOwner.scenePipeline==first.pipeline,"Scene uses the configured owned pipeline");Check(!scene.isDirty,"Configured scene is saved");Check(OutlineRendererInstaller.DetectPipeline(scene)==first.pipeline,"Detection finds the installed scene override");
   foreach(var path in first.rendererPaths){var rd=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(path);var effects=rd.rendererFeatures.OfType<ElevatorSilhouetteOutlineFeature>().ToArray();Check(effects.Count(f=>f.isActive)==1,"Exactly one active outline feature: "+path);var f=effects.First(x=>x.isActive);Check(f.maskShader&&f.distanceShader,"Coverage and distance shaders are serialized");var map=new SerializedObject(rd).FindProperty("m_RendererFeatureMap");Check(map.arraySize==rd.rendererFeatures.Count&&Enumerable.Range(0,map.arraySize).All(i=>map.GetArrayElementAtIndex(i).longValue!=0),"Feature IDs are serialized and resolvable");}
   second=OutlineRendererInstaller.Install(source,scene,true);Check(second.pipeline==first.pipeline&&second.createdAssets.Length==0&&second.addedFeatures==0,"Repeated setup reuses the existing assets and feature");
   var model=new SerializedObject(first.pipeline);var slots=model.FindProperty("m_RendererDataList");Check(slots.arraySize==pso.FindProperty("m_RendererDataList").arraySize,"Renderer slot count is preserved");Check(model.FindProperty("m_DefaultRendererIndex").intValue==pso.FindProperty("m_DefaultRendererIndex").intValue,"Default renderer index is preserved");Check(model.FindProperty("m_RenderScale").floatValue==pso.FindProperty("m_RenderScale").floatValue,"Existing render scale is preserved");
   bool nullRejected=false;try{OutlineRendererInstaller.Install(null,scene,false);}catch(InvalidOperationException){nullRejected=true;}Check(nullRejected,"Missing URP input reports an actionable error");
   var temporary=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);bool unsavedRejected=false;try{OutlineRendererInstaller.Install(source,temporary,true);}catch(InvalidOperationException){unsavedRejected=true;}Check(unsavedRejected,"Unsaved scenes are rejected before installation");EditorSceneManager.CloseScene(temporary,true);
   Check(Object.FindObjectsByType<ElevatorSceneRendering>(FindObjectsInactive.Include,FindObjectsSortMode.None).Count(o=>o.gameObject.scene==scene)==1,"Repeated linking does not create duplicate scene overrides");EditorSceneManager.OpenScene(scenePath,OpenSceneMode.Single);var loaded=Object.FindFirstObjectByType<ElevatorSceneRendering>();Check(loaded.scenePipeline==first.pipeline,"Saved scene reopens with the configured pipeline");Check(AssetDatabase.GetDependencies(scenePath,true).Contains(AssetDatabase.GetAssetPath(first.pipeline)),"Pipeline is a real scene build dependency");
  }catch(Exception e){error=e.ToString();}finally{if(window)window.Close();}
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,passed=checks.Count(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),checks,pipeline=first!=null?AssetDatabase.GetAssetPath(first.pipeline):null,renderers=first?.rendererPaths,error},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+"InstallerVerification.json",report);return report;
 }
}